insert into public.sejong_notices as target (id,published_on,payload) values ('recruit','2026-10-08','{"id":"recruit","category":"채용","title":"세종문화회관 공연장 안내원 모집 안내","date":"2026-10-08","content":"관객의 특별한 하루를 함께 만들어갈 공연장 안내원 모집 안내입니다. 본 내용은 채용 상세 페이지 구현을 위한 예시이며 실제 채용 접수는 진행되지 않습니다.","body":"관객의 특별한 하루를 함께 만들어갈 공연장 안내원을 모집합니다. 본 내용은 채용 상세 페이지 구현을 위한 예시이며 실제 채용 접수는 진행되지 않습니다.","details":[["모집분야","공연장 관객 안내 및 운영 지원"],["근무형태","공연 일정에 따른 탄력 근무"],["전형","서류 검토 → 면접 → 결과 안내"]]}'::jsonb) on conflict (id) do update set published_on=excluded.published_on,payload=excluded.payload where row(target.published_on,target.payload) is distinct from row(excluded.published_on,excluded.payload);
