insert into public.sejong_notices as target (id,published_on,payload) values ('academy-notice','2026-10-05','{"id":"academy-notice","category":"교육","title":"세종예술아카데미 가을학기 수강 안내","date":"2026-10-05","content":"음악과 미술, 예술을 알아가는 즐거움. 가을학기 강좌별 일정과 준비물을 교육 프로그램 상세에서 확인하실 수 있습니다.","body":"음악과 미술, 예술을 알아가는 즐거움. 가을학기 강좌별 일정과 준비물을 교육 프로그램 상세에서 확인하실 수 있습니다.","details":[["분야","클래식 감상 · 미술사 · 예술 인문학"],["신청","교육 프로그램에서 강좌 선택"]]}'::jsonb) on conflict (id) do update set published_on=excluded.published_on,payload=excluded.payload where row(target.published_on,target.payload) is distinct from row(excluded.published_on,excluded.payload);
