insert into public.sejong_pages as target (id,payload,published) values ('/visit/directions','{"path":"/visit/directions","title":"오시는 길·주차","description":"지하철 출구와 공연장 위치, 주차장 진입 안내를 나누어 확인하세요.","blocks":[{"type":"facts","title":"대중교통","items":[{"label":"5호선 광화문역","value":"공연장 방향 출구와 보행 동선을 확인하세요."},{"label":"3호선 경복궁역","value":"광화문 방향으로 이동해 공연장 위치를 확인하세요."},{"label":"목적지","value":"서울특별시 종로구 세종대로 175 세종문화회관"}]},{"type":"map","address":"서울특별시 종로구 세종대로 175","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200352","label":"공연장까지의 대중교통 경로"},{"type":"actions","items":[{"label":"출구·버스 노선 확인","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200352","external":true},{"label":"주차장 출입구·할인 확인","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200390","external":true}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200352","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
