insert into public.sejong_pages as target (id,payload,published) values ('/visit/directions/parking','{"path":"/visit/directions/parking","title":"주차안내","description":"공영주차장 출입구와 관람객 할인 조건을 확인하세요.","blocks":[{"type":"prose","heading":"세종로 공영주차장","paragraphs":["광화문 일대 행사와 교통 상황에 따라 입·출차가 지연될 수 있습니다.","주차 요금과 관람객 할인은 주차장 안내에 따릅니다. 이용한 공연·전시의 할인 조건과 정산 방법을 확인하세요."]},{"type":"actions","items":[{"label":"주차장 출입구와 정산 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200390","external":true},{"label":"대중교통으로 오시는 길","href":"/visit/directions","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200390","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
