insert into public.sejong_pages as target (id,payload,published) values ('/visit/spaces','{"path":"/visit/spaces","title":"공간안내","description":"공연장과 전시 공간의 위치·용도·좌석배치를 확인하세요.","blocks":[{"type":"prose","heading":"공간 선택","paragraphs":["공연장 이름은 관람 티켓에 표시되어 있습니다. 출발 전에 정확한 공연장과 입장 위치를 확인하세요."]},{"type":"actions","items":[{"label":"공식 좌석배치도","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200368","external":true},{"label":"대관시설 비교","href":"/rental/compare","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200368","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
