insert into public.sejong_pages as target (id,payload,published) values ('/visit/amenities','{"path":"/visit/amenities","title":"편의시설","description":"관람 전후에 이용할 수 있는 편의시설과 위치를 확인하세요.","blocks":[{"type":"facts","title":"시설 이용","items":[{"label":"위치","value":"편의시설은 공연장과 층별로 다릅니다. 방문할 공간의 위치 안내를 확인하세요."},{"label":"이용 시간","value":"공연·전시 운영 시간과 시설별 영업시간을 확인하세요."},{"label":"도움이 필요할 때","value":"현장 안내 직원 또는 고객센터 02-399-1000에 문의하세요."}]},{"type":"actions","items":[{"label":"편의시설 위치 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388","external":true},{"label":"장애인 이용안내","href":"/visit/accessibility","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
