insert into public.sejong_pages as target (id,payload,published) values ('/visit/amenities/dining','{"path":"/visit/amenities/dining","title":"F&B · 다이닝","description":"식음 공간의 위치와 운영 여부를 방문 전에 확인하세요.","blocks":[{"type":"prose","heading":"공연 전후의 식사","paragraphs":["공연장별 매장과 휴게 공간의 위치를 먼저 확인하세요. 매장별 운영 시간과 이용 조건은 현장 안내에 따릅니다."]},{"type":"actions","items":[{"label":"식음·휴게시설 확인","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388","external":true},{"label":"관람 유의사항","href":"/visit/etiquette","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
