insert into public.sejong_pages as target (id,payload,published) values ('/visit/accessibility','{"path":"/visit/accessibility","title":"장애인 이용안내","description":"이동 동선과 휠체어석, 관람 지원 서비스를 확인하세요.","blocks":[{"type":"facts","title":"관람 지원","items":[{"label":"좌석","value":"휠체어석과 동반 관람 좌석은 공연별 판매처에서 확인하세요."},{"label":"이동","value":"공연장별 승강기와 접근 가능한 출입구를 확인하세요."},{"label":"사전 문의","value":"이용할 공연장과 필요한 지원 내용을 고객센터 02-399-1000에 알려 주세요."}]},{"type":"actions","items":[{"label":"접근 가능한 출입구·서비스","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200353","external":true},{"label":"공연장 위치","href":"/visit/spaces","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200353","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
