insert into public.sejong_pages as target (id,payload,published) values ('/visit/etiquette','{"path":"/visit/etiquette","title":"관람 유의사항","description":"관람 연령·입장 시간·변경과 취소 조건을 예매 전에 확인하세요.","blocks":[{"type":"facts","title":"공연별로 확인할 사항","items":[{"label":"관람 연령","value":"프로그램 상세의 관람 연령과 입장 제한을 확인하세요."},{"label":"입장","value":"지연 입장과 재입장 가능 시점은 작품과 현장 운영에 따라 다릅니다."},{"label":"촬영·음식물","value":"공연장과 작품의 촬영·녹음·음식물 반입 안내를 따라 주세요."},{"label":"변경·취소","value":"예매처와 취소 시점에 따른 수수료·환불 조건을 확인하세요."}]},{"type":"actions","items":[{"label":"티켓 구매·변경·취소 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322","external":true},{"label":"프로그램 확인","href":"/programs","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
