insert into public.sejong_pages as target (id,payload,published) values ('/about/arts-center','{"path":"/about/arts-center","title":"꿈의숲 아트센터","description":"꿈의숲아트센터의 공연·전시와 공간·방문 정보를 확인하세요.","blocks":[{"type":"prose","heading":"꿈의숲아트센터","paragraphs":["방문할 공연장과 주소를 확인하세요. 광화문 세종문화회관과 위치가 다릅니다. 프로그램 일정과 교통·주차 정보는 아트센터 안내를 이용하세요."]},{"type":"actions","items":[{"label":"꿈의숲아트센터 프로그램·방문 안내","href":"https://www.sejongpac.or.kr/dfac/main/main.do","external":true}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/dfac/main/main.do","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
