insert into public.sejong_pages as target (id,payload,published) values ('/policy/privacy','{"path":"/policy/privacy","title":"개인정보처리방침","description":"개인정보 처리 항목·목적·보유 기간과 권리 행사 방법을 확인하세요.","blocks":[{"type":"prose","heading":"개인정보 처리 확인","paragraphs":["로그인과 회원 데이터는 인증한 계정의 접근 권한으로 관리됩니다. 개인정보 문의와 기관 서비스의 처리방침은 해당 서비스의 최신 게시 내용을 확인하세요."]},{"type":"actions","items":[{"label":"기관 홈페이지의 개인정보처리방침","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200148","external":true},{"label":"회원정보 관리","href":"/account/profile","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
