insert into public.sejong_pages as target (id,payload,published) values ('/sitemap','{"path":"/sitemap","title":"사이트맵","description":"프로그램·대관·방문·소식·기관 정보의 주요 경로를 확인하세요.","blocks":[{"type":"prose","heading":"사이트맵","paragraphs":["원하는 업무의 메뉴를 선택하면 해당 안내로 이동합니다. 회원의 예약·관심 프로그램·관람노트는 마이페이지에서 확인할 수 있습니다."]},{"type":"actions","items":[{"label":"프로그램","href":"/programs","external":false},{"label":"대관","href":"/rental","external":false},{"label":"이용안내","href":"/visit","external":false},{"label":"소식과 혜택","href":"/news","external":false},{"label":"세종문화회관","href":"/about","external":false},{"label":"마이페이지","href":"/account","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
insert into sejong_private.content_revisions(entity_table,entity_id,revision,raw_source,source_path) select 'sejong_pages','/sitemap',1,'{"path":"/sitemap","title":"사이트맵","description":"프로그램·대관·방문·소식·기관 정보의 주요 경로를 확인하세요.","blocks":[{"type":"prose","heading":"사이트맵","paragraphs":["원하는 업무의 메뉴를 선택하면 해당 안내로 이동합니다. 회원의 예약·관심 프로그램·관람노트는 마이페이지에서 확인할 수 있습니다."]},{"type":"actions","items":[{"label":"프로그램","href":"/programs","external":false},{"label":"대관","href":"/rental","external":false},{"label":"이용안내","href":"/visit","external":false},{"label":"소식과 혜택","href":"/news","external":false},{"label":"세종문화회관","href":"/about","external":false},{"label":"마이페이지","href":"/account","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,'src/catalog/page-content.ts' where not exists(select 1 from sejong_private.content_revisions where entity_table='sejong_pages' and entity_id='/sitemap' and revision=1);
insert into public.sejong_pages as target (id,payload,published) values ('/search','{"path":"/search","title":"통합검색","description":"프로그램 이름·장르·공간을 검색해 상세 정보로 이동하세요.","blocks":[{"type":"prose","heading":"검색 범위","paragraphs":["공연·전시·교육 프로그램과 장소·장르를 검색할 수 있습니다. 검색어를 바꾸거나 프로그램 분류를 선택해 결과를 좁혀 보세요."]},{"type":"actions","items":[{"label":"프로그램 검색","href":"/programs","external":false},{"label":"고객 문의","href":"/visit/support","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,true) on conflict (id) do update set payload=excluded.payload,published=excluded.published where row(target.payload,target.published) is distinct from row(excluded.payload,excluded.published);
insert into sejong_private.content_revisions(entity_table,entity_id,revision,raw_source,source_path) select 'sejong_pages','/search',1,'{"path":"/search","title":"통합검색","description":"프로그램 이름·장르·공간을 검색해 상세 정보로 이동하세요.","blocks":[{"type":"prose","heading":"검색 범위","paragraphs":["공연·전시·교육 프로그램과 장소·장르를 검색할 수 있습니다. 검색어를 바꾸거나 프로그램 분류를 선택해 결과를 좁혀 보세요."]},{"type":"actions","items":[{"label":"프로그램 검색","href":"/programs","external":false},{"label":"고객 문의","href":"/visit/support","external":false}]}],"status":"published","revision":1,"sourceUrl":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505","verifiedAt":"2026-10-23T00:00:00+09:00"}'::jsonb,'src/catalog/page-content.ts' where not exists(select 1 from sejong_private.content_revisions where entity_table='sejong_pages' and entity_id='/search' and revision=1);
